```
function sleep(ms){return new Promise(r=>setTimeout(r,ms));}
function st(){return sdk.getState();}

async function healIfNeeded(){
  const p=st()?.player; if(!p) return;
  const hp=p.hitpoints ?? 10;
  if(hp<=5){
    try{ await bot.eatFood(/bread|shrimp/i); }catch(e){}
  }
}

async function killByName(re, timeoutMs){
  const t0=Date.now();
  let lastIdx=-1;
  while(Date.now()-t0<timeoutMs){
    const s=st();
    if(!s){await sleep(400);continue;}
    const npc=s.nearbyNpcs.filter(n=>re.test(n.name)).filter(n=>n.optionsWithIndex.some(o=>/attack/i.test(o.text))).sort((a,b)=>a.distance-b.distance)[0];
    if(!npc){ await sleep(800); continue; }
    if(npc.distance>9){
      try{ await bot.walkTo(npc.x,npc.z,3,{timeout:15000}); }catch(e){}
      continue;
    }
    const idx=npc.index;
    try{ await bot.attack(npc,4000); }catch(e){}
    // wait until npc gone or 12s
    await sdk.waitForCondition(s=>!s.nearbyNpcs.some(n=>n.index===idx),12000).catch(()=>{});
    const s2=st();
    if(s2 && !s2.nearbyNpcs.some(n=>n.index===idx)) return true;
  }
  return false;
}

const results={};
const targets=[[/^imp$/i,40000],[/^giant rat$/i,45000],[/^chicken$/i,30000],[/^duck$/i,30000],[/^farmer$/i,60000]];
const deadline=Date.now()+220000;
for(const [re,ms] of targets){
  if(Date.now()>=deadline) break;
  const r=await killByName(re, Math.min(ms, deadline-Date.now()));
  results[re.source]=r;
  await healIfNeeded();
}
return {results, hp: st()?.player?.hitpoints, pos:[st()?.player?.worldX,st()?.player?.worldZ], atkXp: sdk.getSkillXp('Attack'), strXp:sdk.getSkillXp('Strength')};
```

