import { readdirSync, readFileSync } from 'fs';

const dir = 'wiki/npcs';
const files = readdirSync(dir).filter(f => f.endsWith('.md'));
const out = [];
for (const f of files) {
  const txt = readFileSync(dir + '/' + f, 'utf8');
  const lvlM = txt.match(/\*\*Combat Level\*\*\s*\|\s*([\d\-]+)/);
  if (!lvlM) continue;
  const lvlParts = lvlM[1].split('-').map(Number);
  const lvl = lvlParts[lvlParts.length - 1];
  if (!lvl) continue;
  const coords = [...txt.matchAll(/\((\d{4}),\s*(\d{4})\)/g)];
  const inLum = coords.filter(m => {
    const x = +m[1], z = +m[2];
    return x >= 3150 && x <= 3280 && z >= 3190 && z <= 3380;
  });
  if (inLum.length === 0) continue;
  const name = txt.match(/^# (.+)$/m)?.[1] ?? f;
  out.push({ name, lvl, val: Math.log(1 + lvl), coord: `(${inLum[0][1]},${inLum[0][2]})`, n: inLum.length });
}
out.sort((a, b) => b.val - a.val);
for (const o of out) console.log(`${o.val.toFixed(2)}  L${o.lvl}  ${o.name}  ${o.coord}  x${o.n}`);

